    private val cache = HashMap<String, androidx.compose.ui.graphics.Path?>()

    fun path(name: String): androidx.compose.ui.graphics.Path? = cache.getOrPut(name) {
        val raw = DATA[name] ?: return@getOrPut null
        val evenOdd = raw.startsWith("E|")
        val d = if (evenOdd) raw.substring(2) else raw
        try {
            val p = PathParser.createPathFromPathData(d).asComposePath()
            if (evenOdd) p.fillType = PathFillType.EvenOdd
            p
        } catch (e: Exception) { null }
    }

