@Composable
fun GlyphIcon(name: String, tint: Color, size: Dp = 24.dp, modifier: Modifier = Modifier) {
    val path = remember(name) { Glyphs.path(name) }
    Canvas(modifier.size(size)) {
        val p = path
        if (p != null) {
            val s = this.size.minDimension / 24f
            scale(s, s, pivot = Offset.Zero) { drawPath(p, tint) }
        }
    }
}
